using System;
using System.IO;
using System.Linq;
namespace Touchfish {
public partial class PanelWindow {
 public void PreviewLowCostScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;Check(catalog.Deckable(catalog.Pool("classic-2014")).Where(c=>c.Cost>=1&&c.Cost<=2&&c.CardClass!="HUNTER").All(matchRules.Supports),"Non-Hunter low-cost cards all enabled");VerifyLowCostTcp(folder);File.WriteAllText(Path.Combine(folder,"low-cost-verification.txt"),"PASS: "+(checks-before)+" focused assertions; spell-after timing, summon-after-battlecry timing, private Pirate draw, health swapping, weapon durability and actual loopback TCP.");}
 void VerifyLowCostTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="ROGUE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Low cost peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}var knife=g.Summon(0,"VAN_NEW1_019");var pyro=g.Summon(0,"VAN_NEW1_020");int enemyHealth=g.Players[1].Health;int brewer=Inject(g,"EX1_049"),shield=Inject(g,"CS2_004"),murloc=Inject(g,"EX1_506");PublishLan();BeginCard(brewer);ClickEmptySlot(0,2);Check(pending=="play","Brewmaster asks target after position");ClickMatchTarget(new MatchTarget(0,knife.Id));PumpLan(()=>guest.match.Players[0].Board.Count==2&&guest.match.Players[0].Board.All(u=>u.Id!=knife.Id),"Brewmaster return reaches opponent");Check(g.Players[1].Health==enemyHealth&&g.Players[0].Hand.Any(h=>h.CardId=="VAN_NEW1_019"),"Knife returned before summon trigger and hand restored");BeginCard(shield);ClickMatchTarget(new MatchTarget(0,pyro.Id));PumpLan(()=>guest.match.Players[0].Board.Any(u=>u.Id==pyro.Id&&u.Health==3),"After-spell Pyromancer state reaches guest");Check(g.Players[0].Board.Single(u=>u.CardId=="VAN_EX1_049").Health==1,"Shield applied before Pyromancer damage");var returned=match.Players[0].Hand.Single(h=>h.CardId=="VAN_NEW1_019");BeginCard(returned.Id);ClickEmptySlot(0,2);BeginCard(murloc);ClickEmptySlot(0,3);PumpLan(()=>guest.match.Players[1].Health==enemyHealth-2,"Main summon and battlecry token each throw one dagger");Check(g.Players[0].Board.Count==5&&guest.match.Players[0].Hand.Count==0,"Board and private hand remain consistent");Render(Path.Combine(folder,"135-low-cost-triggers-codex.png"));DoMatch("end");PumpLan(()=>guest.match.Active==1,"Guest turn starts");
  g.Players[1].Hand.Clear();g.Players[1].Mana=10;g.Players[1].Deck.Clear();g.Players[1].Deck.AddRange(new[]{"VAN_CS2_182","VAN_NEW1_018"});var mirror=g.Summon(1,"VAN_CS2_mirror");g.EquipRaw(0,"GAME_DAGGER",1,2,false);int alchemist=Inject(g,"EX1_059",1),parrot=Inject(g,"NEW1_016",1),corsair=Inject(g,"NEW1_025",1);PublishLan();PumpLan(()=>guest.match.Players[1].Hand.Any(h=>h.Id==alchemist),"Guest battlecries reach hand");guest.BeginCard(alchemist);guest.ClickEmptySlot(1,1);guest.ClickMatchTarget(new MatchTarget(1,mirror.Id));PumpLan(()=>!guest.lanWaiting&&g.Players[1].Board.All(u=>u.Id!=mirror.Id),"Alchemist zero attack target dies on authority");guest.BeginCard(parrot);guest.ClickEmptySlot(1,1);PumpLan(()=>!guest.lanWaiting&&guest.match.Players[1].Hand.Any(h=>h.CardId=="VAN_NEW1_018"),"Private Pirate draw reaches guest only");Check(g.Players[1].Deck.Single()=="VAN_CS2_182"&&LanProtocol.View(g,0,"cost",1).Players[1].Hand.Length==0,"Pirate draw preserves order and masks hand from public view");guest.BeginCard(corsair);guest.ClickEmptySlot(1,2);PumpLan(()=>!guest.lanWaiting&&g.Players[0].WeaponDurability==1,"Corsair weapon durability synchronizes");Check(guest.match.Players[0].WeaponDurability==1,"Guest sees resulting public weapon durability");guest.Opacity=1;guest.Render(Path.Combine(folder,"136-low-cost-guest-codex.png"));guest.Opacity=0;
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
}
